import sys
data = sys.stdin.read().split()
if data:
    n, k = int(data[0]), int(data[1])
    nums = data[2:2+n]
    res = []
    for i in range(0, n, k):
        chunk = nums[i:i+k]
        if len(chunk) == k: res.extend(reversed(chunk))
        else: res.extend(chunk)
    print(' '.join(res))
